// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager, IERC20, IGlpManager, IRewardRouterV2} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public {
        c = new DnGmxBatchingManager();
    }

    function testFuzz_property(address keeper, uint256 t1, uint256 t2) public {
        // Use the owner to initialize with the fuzzed keeper.
        address owner = address(this);
        IERC20 zeroToken = IERC20(address(0));
        IRewardRouterV2 zeroRouter = IRewardRouterV2(address(0));
        IGlpManager zeroGlpManager = IGlpManager(address(0));
        address zeroVault = address(0);

        // initialize may revert if the owner/init conditions are not met, but on a fresh C they are.
        try c.initialize(zeroToken, zeroToken, zeroRouter, zeroGlpManager, zeroVault, keeper) {} catch {}

        // Only keeper can call executeBatchDeposit; make the fuzzed address the keeper.
        // Deploy a minimal GlpManager stub so glpManager.vault() returns a plain address.
        GlpManagerStub glpStub = new GlpManagerStub();
        // Re-initialize is not possible; call the internal init path through initialize was already done.
        // Instead, we work with the deployed C and the zero glpManager: glpManager.vault() would revert.
        // To avoid that, we must route glpManager to a contract with vault(). Since initialize already ran,
        // we cannot change it. We therefore use a fresh C in the test and initialize it with the stub.
        DnGmxBatchingManager fresh = new DnGmxBatchingManager();
        fresh.initialize(zeroToken, zeroToken, zeroRouter, IGlpManager(address(glpStub)), zeroVault, keeper);

        // Ensure the keeper is the caller.
        vm.prank(keeper);
        try fresh.executeBatchDeposit() {
            // First call succeeded; advance time by 15 minutes exactly.
            vm.warp(block.timestamp + 15 minutes);
            vm.prank(keeper);
            try fresh.executeBatchDeposit() {
                // Second call also succeeded. On the reference this is allowed because exactly 15 minutes
                // passed (require block.timestamp > last + 15 minutes). On the bug it is also allowed.
                // To expose the difference, we need a second call that would be within the cooldown if
                // lastUnpauseTimestamp had been updated. We do that by making the first call at some time,
                // then the second at a time strictly less than 15 minutes later. On the reference the first
                // call sets lastUnpauseTimestamp = t1, so a second call at t2 < t1+15min must revert.
                // On the bug it never sets it (stays 0), so the second call succeeds (since block.timestamp > 0 + 15min
                // if t2 >= 15min, or more generally if block.timestamp > 15 minutes). To keep the domain wide
                // and guarantee the bug succeeds, require t2 > 15 minutes.
                // We therefore need to control the timestamps more directly. Below we instead perform the
                // first call at a controllable time and the second within the cooldown relative to it.
                // Since we already did the calls above, we use a second fresh instance for the actual test.
            } catch {}
        } catch {}

        // Fresh instance for the real test.
        DnGmxBatchingManager target = new DnGmxBatchingManager();
        GlpManagerStub glpStub2 = new GlpManagerStub();
        target.initialize(zeroToken, zeroToken, zeroRouter, IGlpManager(address(glpStub2)), zeroVault, keeper);

        // Admissible domain: t1 is the time of the first call, t2 the time of the second call.
        // The bug succeeds on the second call whenever block.timestamp > 15 minutes (because lastUnpauseTimestamp
        // remains 0). The reference succeeds only if t2 > t1 + 15 minutes.
        // We choose t1 = 0 and t2 in (15 minutes, 15 minutes + epsilon) so the reference reverts on the
        // second call and the bug succeeds.
        // But t1 is fuzzed here; to make the property universally false on the bug, we bound t2 to be
        // in the window (15 minutes, 15 minutes + 1) when t1 = 0. Since t1 is fuzzed, we instead perform
        // the first call at t1 and the second at t2, and assert the reference property:
        //   if second call succeeds then t2 > t1 + 15 minutes, or the first call didn't succeed.
        // Concretely, we make t1 = 0 (or any time) and t2 = t1 + 15 minutes - 1 to be within the cooldown.
        // To keep the fuzz parameters as deciding values, we bound t1 in [0, 1e18] and bound t2 in
        // [15 minutes, 15 minutes + 1] so that the bug succeeds on the second call while the reference
        // reverts (since lastUnpauseTimestamp = t1 = 0, and t2 < 15 minutes + 0 + 15 minutes is not guaranteed;
        // wait, 15 minutes < 15 minutes + 15 minutes, so t2=15 minutes is within cooldown relative to t1=0).
        // So set t1 = 0 and t2 = 15 minutes. Then reference: require(15 min > 0 + 15 min) is false -> revert.
        // Bug: lastUnpauseTimestamp stays 0, require(15 min > 0 + 15 min) is false -> revert too! Because
        // 15 minutes is not strictly greater than 15 minutes. We need t2 slightly larger than 15 minutes,
        // e.g. 15 minutes + 1 second. Then reference: 15m+1s > 0+15m true -> succeeds (first call), then
        // second call at same time t2: lastUnpauseTimestamp = t2 from first call, require(t2 > t2+15m) false -> revert.
        // Bug: first call sets last=0, second call at same t2: require(t2 > 0+15m) true -> succeeds.
        // So we want two calls at the SAME timestamp t2 > 15 minutes, with t1 being the initial time (0).
        // Since lastUnpauseTimestamp is 0 and the first call at t2 sets it to t2 on the reference, a second
        // call at the same t2 must revert on the reference but succeeds on the bug.
        // Therefore: perform two calls at the same timestamp t2 > 15 minutes, and assert that not both succeed.
        // On the reference the second reverts; on the bug both succeed.
        // The fuzzed parameter t2 is the time of both calls, with t2 > 15 minutes.
        t2 = bound(t2, 15 minutes + 1, type(uint64).max);
        vm.warp(t2);

        vm.prank(keeper);
        bool firstOk;
        try target.executeBatchDeposit() { firstOk = true; } catch { firstOk = false; }

        vm.prank(keeper);
        bool secondOk;
        try target.executeBatchDeposit() { secondOk = true; } catch { secondOk = false; }

        // General rule: on the reference, after the first successful call at time t, the second call at the
        // same time t must not succeed because the cooldown has not elapsed. On the buggy contract it does.
        // So assert that it is not the case that both calls succeed at the same timestamp within the cooldown.
        assertTrue(!(firstOk && secondOk), "second executeBatchDeposit within cooldown must revert");
    }
}

contract GlpManagerStub is IGlpManager {
    function vault() external pure override returns (address) {
        return address(0);
    }
}
